import { Container } from "@gunjo/ui"
import { LegalMattersClient } from "./LegalMattersClient"
import { companyName, departmentName, viewerName } from "./data"

export const metadata = {
  title: "法務相談・案件管理 | 群青ホールディングス 法務・コンプライアンス部",
  description:
    "事業部門から法務部に寄せられる相談の受付・担当割当・期限管理・回答までを一元管理する画面。段階別ボード、期限アラート、依頼元とのやり取り、担当者別の負荷状況に対応。",
}

export default function LegalMattersPage() {
  return (
    <Container size="2xl" className="py-5 sm:py-8">
      <LegalMattersClient
        companyName={companyName}
        departmentName={departmentName}
        viewerName={viewerName}
      />
    </Container>
