"use client"

import * as React from "react"
import {
  IconCheck,
  IconCornerDownRight,
  IconMessage2,
  IconMessagePlus,
  IconRotateClockwise,
  IconScale,
  IconBuildingStore,
} from "@tabler/icons-react"
import {
  Badge,
  Button,
  Checkbox,
  EmptyState,
  Icon,
  PersonCell,
  Separator,
  Textarea,
} from "@gunjo/ui"
import type { ThreadComment, ThreadReply, ThreadSide } from "./data"

/**
 * 依頼元（事業部門）と法務担当のやり取り欄。
 *
 * `@gunjo/ui` には「返信つき・解決済みを区別できるコメントスレッド」に相当する
 * コンポーネントが無いため（ChatMessage は role が assistant/user/system 固定の
 * AIチャット用）、Card / PersonCell / Badge / Textarea / Button を組み合わせて
 * この画面用に組んでいる。
 */

const SIDE_META: Record<
  ThreadSide,
  { badge: "info" | "secondary"; icon: typeof IconScale; label: string }
> = {
  法務: { badge: "info", icon: IconScale, label: "法務" },
  依頼元: { badge: "secondary", icon: IconBuildingStore, label: "依頼元" },
}

function AuthorLine({
  side,
  author,
  affiliation,
  at,
  size = "sm",
}: {
  side: ThreadSide
  author: string
  affiliation: string
  at: string
  size?: "sm" | "md"
}) {
  const meta = SIDE_META[side]
  return (
    <div className="flex flex-wrap items-start justify-between gap-x-3 gap-y-1">
      <PersonCell
        size={size}
        name={author}
        secondary={affiliation}
        avatar={{ fallback: author.slice(0, 1) }}
        className="min-w-0"
      />
      <div className="flex shrink-0 items-center gap-2">
        <Badge variant={meta.badge} size="sm" icon={<meta.icon />}>
          {meta.label}
        </Badge>
        <time className="text-xs tabular-nums text-muted-foreground">{at}</time>
      </div>
    </div>
  )
}

function ReplyItem({ reply }: { reply: ThreadReply }) {
  return (
    <li className="border-l-2 border-border pl-3 sm:pl-4">
      <div className="mb-1 flex items-center gap-1.5 text-muted-foreground">
        <Icon icon={IconCornerDownRight} size="xs" decorative />
        <span className="text-xs">返信</span>
      </div>
      <AuthorLine
        side={reply.side}
        author={reply.author}
        affiliation={reply.affiliation}
        at={reply.at}
      />
      <p className="mt-2 whitespace-pre-wrap text-sm leading-relaxed text-foreground">
        {reply.body}
      </p>
    </li>
  )
}

export interface ConsultationThreadProps {
  comments: ThreadComment[]
  /** 返信を投稿する（モックなので親の state に積むだけ） */
  onReply: (commentId: string, body: string) => void
  /** 解決済み / 未解決の切り替え */
  onToggleResolved: (commentId: string) => void
  /** 新しい論点を立てる */
  onAddComment: (body: string) => void
  /** 見出しの id（section の aria-labelledby 用） */
  headingId: string
}

export function ConsultationThread({
  comments,
  onReply,
  onToggleResolved,
  onAddComment,
  headingId,
}: ConsultationThreadProps) {
  const [openOnly, setOpenOnly] = React.useState(false)
  const [replyTo, setReplyTo] = React.useState<string | null>(null)
  const [replyBody, setReplyBody] = React.useState("")
  const [newBody, setNewBody] = React.useState("")
  const [composerOpen, setComposerOpen] = React.useState(false)

  const openCount = comments.filter((c) => !c.resolved).length
  const shown = openOnly ? comments.filter((c) => !c.resolved) : comments

  const submitReply = (commentId: string) => {
    const body = replyBody.trim()
    if (!body) return
    onReply(commentId, body)
    setReplyBody("")
    setReplyTo(null)
  }

  const submitComment = () => {
    const body = newBody.trim()
    if (!body) return
    onAddComment(body)
    setNewBody("")
    setComposerOpen(false)
  }

  return (
    <section aria-labelledby={headingId} className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
        <h3
          id={headingId}
          className="flex items-center gap-2 text-base font-semibold text-foreground"
        >
          <Icon icon={IconMessage2} size="sm" decorative />
          依頼元とのやり取り
          <span className="text-sm font-normal text-muted-foreground">
            （全 {comments.length} 件・未解決 {openCount} 件）
          </span>
        </h3>
        <Checkbox
          label="未解決のみ表示"
          checked={openOnly}
          onCheckedChange={setOpenOnly}
        />
      </div>

      {shown.length === 0 ? (
        <EmptyState
          headingLevel={4}
          icon={<Icon icon={IconMessage2} size="lg" decorative />}
          title={openOnly ? "未解決のやり取りはありません" : "まだやり取りがありません"}
          description={
            openOnly
              ? "この案件の論点はすべて解決済みです。"
              : "依頼元への確認事項があれば、ここに書き込むと依頼者に通知されます。"
          }
        />
      ) : (
        <ol className="space-y-4">
          {shown.map((comment) => {
            const isReplying = replyTo === comment.id
            const replyFieldId = `reply-${comment.id}`
            return (
              <li key={comment.id}>
                <article
                  aria-label={`${comment.author}（${comment.affiliation}）${comment.at} の投稿${
                    comment.resolved ? "・解決済み" : "・未解決"
                  }`}
                  className="rounded-lg border border-border bg-card p-3 sm:p-4"
                >
                  <AuthorLine
                    side={comment.side}
                    author={comment.author}
                    affiliation={comment.affiliation}
                    at={comment.at}
                    size="md"
                  />

                  <p className="mt-3 whitespace-pre-wrap text-sm leading-relaxed text-foreground">
                    {comment.body}
                  </p>

                  <div className="mt-3 flex flex-wrap items-center gap-2">
                    <Badge
                      variant={comment.resolved ? "success" : "warning"}
                      size="sm"
                      icon={
                        comment.resolved ? <IconCheck /> : <IconRotateClockwise />
                      }
                    >
                      {comment.resolved ? "解決済み" : "未解決"}
                    </Badge>
                    {comment.replies.length > 0 ? (
                      <span className="text-xs text-muted-foreground">
                        返信 {comment.replies.length} 件
                      </span>
                    ) : null}
                  </div>

                  {comment.replies.length > 0 ? (
                    <>
                      <Separator className="my-3" />
                      <ol className="space-y-4">
                        {comment.replies.map((reply) => (
                          <ReplyItem key={reply.id} reply={reply} />
                        ))}
                      </ol>
                    </>
                  ) : null}

                  <Separator className="my-3" />

                  <div className="flex flex-wrap gap-2">
                    <Button
                      type="button"
                      size="sm"
                      variant="outline"
                      onClick={() => {
                        setReplyTo(isReplying ? null : comment.id)
                        setReplyBody("")
                      }}
                      aria-expanded={isReplying}
                      aria-controls={isReplying ? replyFieldId : undefined}
                    >
                      返信する
                    </Button>
                    <Button
                      type="button"
                      size="sm"
                      variant="ghost"
                      onClick={() => onToggleResolved(comment.id)}
                    >
                      {comment.resolved ? "未解決に戻す" : "解決済みにする"}
                    </Button>
                  </div>

                  {isReplying ? (
                    <div className="mt-3 space-y-2">
                      <Textarea
                        id={replyFieldId}
                        label={`${comment.author} さんへの返信`}
                        rows={4}
                        maxLength={1000}
                        showCount
                        value={replyBody}
                        placeholder="確認したいこと、法務としての見解を書いてください。"
                        onChange={(e) => setReplyBody(e.target.value)}
                      />
                      <div className="flex flex-wrap gap-2">
                        <Button
                          type="button"
                          size="sm"
                          onClick={() => submitReply(comment.id)}
                          disabled={replyBody.trim().length === 0}
                        >
                          返信を投稿
                        </Button>
                        <Button
                          type="button"
                          size="sm"
                          variant="ghost"
                          onClick={() => {
                            setReplyTo(null)
                            setReplyBody("")
                          }}
                        >
                          取消
                        </Button>
                      </div>
                    </div>
                  ) : null}
                </article>
              </li>
            )
          })}
        </ol>
      )}

      <div className="rounded-lg border border-dashed border-border p-3 sm:p-4">
        {composerOpen ? (
          <div className="space-y-2">
            <Textarea
              id="new-thread-comment"
              label="依頼元への確認・連絡"
              rows={5}
              maxLength={2000}
              showCount
              value={newBody}
              placeholder="例：第8条3項の対象データに個人情報が含まれるかを確認させてください。"
              onChange={(e) => setNewBody(e.target.value)}
            />
            <div className="flex flex-wrap gap-2">
              <Button
                type="button"
                size="sm"
                onClick={submitComment}
                disabled={newBody.trim().length === 0}
              >
                投稿
              </Button>
              <Button
                type="button"
                size="sm"
                variant="ghost"
                onClick={() => {
                  setComposerOpen(false)
                  setNewBody("")
                }}
              >
                取消
              </Button>
            </div>
          </div>
        ) : (
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => setComposerOpen(true)}
          >
            <Icon icon={IconMessagePlus} size="sm" decorative />
            論点を追加する
          </Button>
        )}
      </div>
    </section>
  )
}

"use client"

import { Badge, ExpiryBadge } from "@gunjo/ui"
import { TODAY, formatJpDate, type MatterStatus } from "./data"

const CLOSED: MatterStatus[] = ["回答済み", "完了"]

const LABELS = {
  valid: "期限内",
  expiring: "期限間近",
  expired: "期限超過",
  missing: "未設定",
} as const

/**
 * 希望回答日の表示。
 *
 * ExpiryBadge は「今日 vs 期限」しか見ないため、回答済み・完了の案件でも
 * 期限を過ぎていれば赤い「期限超過」を出してしまう。案件が閉じている場合は
 * 判定を止めて日付だけを見せる、という切り分けをここで持っている。
 */
export function DueIndicator({
  dueDate,
  status,
  showDate = true,
}: {
  dueDate: string
  status: MatterStatus
  showDate?: boolean
}) {
  if (CLOSED.includes(status)) {
    return (
      <span className="inline-flex items-center gap-1.5 whitespace-nowrap text-sm text-muted-foreground">
        <Badge variant="outline" size="sm">
          対応済み
        </Badge>
        <span className="tabular-nums">{formatJpDate(dueDate)}</span>
      </span>
    )
  }

  return (
    <ExpiryBadge
      value={dueDate}
      today={TODAY}
      warnWithinDays={3}
      showDate={showDate}
      labels={LABELS}
      className="whitespace-nowrap"
    />
  )
}

"use client"

import * as React from "react"
import type { ColumnDef } from "@tanstack/react-table"
import {
  IconAlertTriangle,
  IconLayoutColumns,
  IconList,
  IconMessage2,
  IconRefresh,
  IconScale,
  IconInbox,
  IconUserPlus,
} from "@tabler/icons-react"
import {
  Alert,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  DataTable,
  DesktopPageHeader,
  DistributionBar,
  EmptyState,
  Icon,
  KanbanBoard,
  Label,
  Leaderboard,
  ListCard,
  Select,
  SearchInput,
  SegmentedControl,
  Sheet,
  SheetBody,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  Skeleton,
  StatGroup,
  Toggle,
  type ChartDataPoint,
  type KanbanColumn,
  type LeaderboardItem,
} from "@gunjo/ui"
import { DueIndicator } from "./DueIndicator"
import { MatterDetail } from "./MatterDetail"
import {
  CATEGORIES,
  NEXT_STATUS,
  STATUSES,
  TODAY,
  averageResponseDays,
  countByCategory,
  daysUntil,
  formatJpDate,
  isDueSoon,
  isOverdue,
  matters as seedMatters,
  memberName,
  members,
  openThreadCount,
  receivedThisMonth,
  workloadByMember,
  type Matter,
  type MatterCategory,
  type MatterPriority,
  type MatterStatus,
} from "./data"

// ── 見た目のマッピング（色だけに意味を載せないよう、必ずラベルと併記する）──

const STATUS_VARIANT: Record<
  MatterStatus,
  "default" | "secondary" | "info" | "warning" | "success" | "outline"
> = {
  受付待ち: "secondary",
  調査中: "info",
  回答済み: "success",
  保留: "warning",
  完了: "outline",
}

const STATUS_TONE: Record<
  MatterStatus,
  "muted" | "info" | "success" | "warning" | "primary"
> = {
  受付待ち: "muted",
  調査中: "info",
  回答済み: "success",
  保留: "warning",
  完了: "primary",
}

const PRIORITY_VARIANT: Record<
  MatterPriority,
  "destructive" | "warning" | "secondary" | "outline"
> = {
  最優先: "destructive",
  高: "warning",
  中: "secondary",
  低: "outline",
}

const CATEGORY_COLOR: Record<MatterCategory, ChartDataPoint["color"]> = {
  契約審査: "primary",
  法令調査: "info",
  紛争: "destructive",
  知財: "accent",
  コンプライアンス: "warning",
}

const kanbanColumns: KanbanColumn[] = STATUSES.map((s) => ({
  id: s,
  title: s,
  tone: STATUS_TONE[s],
}))

function nowStamp() {
  return `${formatJpDate(TODAY)} 09:00`
}

export interface LegalMattersClientProps {
  companyName: string
  departmentName: string
  viewerName: string
}

export function LegalMattersClient({
  companyName,
  departmentName,
  viewerName,
}: LegalMattersClientProps) {
  const [list, setList] = React.useState<Matter[]>(seedMatters)
  const [loading, setLoading] = React.useState(true)
  const [view, setView] = React.useState<"board" | "list">("board")
  const [query, setQuery] = React.useState("")
  const [category, setCategory] = React.useState<"all" | MatterCategory>("all")
  const [assignee, setAssignee] = React.useState<"all" | "unassigned" | string>(
    "all",
  )
  const [onlyAlert, setOnlyAlert] = React.useState(false)
  const [selectedId, setSelectedId] = React.useState<string | null>(null)

  // 初回の読み込み中表示（モックなので短いタイマーで再現）
  React.useEffect(() => {
    const t = window.setTimeout(() => setLoading(false), 600)
    return () => window.clearTimeout(t)
  }, [])

  const reload = () => {
    setLoading(true)
    window.setTimeout(() => setLoading(false), 600)
  }

  // ── 絞り込み ─────────────────────────────────
  const filtered = React.useMemo(() => {
    const q = query.trim()
    return list.filter((m) => {
      if (category !== "all" && m.category !== category) return false
      if (assignee === "unassigned" && m.assigneeId !== null) return false
      if (assignee !== "all" && assignee !== "unassigned" && m.assigneeId !== assignee)
        return false
      if (onlyAlert && !(isOverdue(m) || isDueSoon(m))) return false
      if (q) {
        const haystack = [
          m.id,
          m.title,
          m.department,
          m.requester,
          m.category,
          m.body,
          m.counterparty ?? "",
        ].join(" ")
        if (!haystack.includes(q)) return false
      }
      return true
    })
  }, [list, query, category, assignee, onlyAlert])

  const selected = React.useMemo(
    () => list.find((m) => m.id === selectedId) ?? null,
    [list, selectedId],
  )

  // ── 統計 ─────────────────────────────────────
  const overdueCount = list.filter((m) => isOverdue(m)).length
  const dueSoonCount = list.filter((m) => isDueSoon(m)).length
  const unassignedCount = list.filter(
    (m) => m.assigneeId === null && m.status !== "完了",
  ).length
  const openComments = list.reduce((n, m) => n + openThreadCount(m), 0)

  const stats = [
    {
      label: "今月の受付",
      value: `${receivedThisMonth(list)} 件`,
      hint: "2026年7月1日以降に受け付けた相談",
    },
    {
      label: "平均回答日数",
      value: `${averageResponseDays(list)} 日`,
      hint: "回答済み案件の受付から回答まで",
    },
    {
      label: "期限超過",
      // Statistic の `tone` は `change` を渡したときにしか効かないため、
      // 値そのものの警告表示は Badge（アイコン＋文字）で担保している
      value: (
        <span className="inline-flex flex-wrap items-center gap-2">
          {overdueCount} 件
          {overdueCount > 0 ? (
            <Badge variant="destructive" size="sm" icon={<IconAlertTriangle />}>
              要対応
            </Badge>
          ) : null}
        </span>
      ),
      hint: `希望回答日まで3日以内：${dueSoonCount} 件`,
    },
    {
      label: "担当未割当",
      value: (
        <span className="inline-flex flex-wrap items-center gap-2">
          {unassignedCount} 件
          {unassignedCount > 0 ? (
            <Badge variant="warning" size="sm" icon={<IconUserPlus />}>
              割当待ち
            </Badge>
          ) : null}
        </span>
      ),
      hint: "受付後、まだ法務担当が決まっていない案件",
    },
  ]

  const categorySegments: ChartDataPoint[] = countByCategory(list).map((c) => ({
    label: c.category,
    value: c.count,
    color: CATEGORY_COLOR[c.category],
  }))

  const workload: LeaderboardItem[] = workloadByMember(list)
    .slice()
    .sort((a, b) => b.count - a.count)
    .map((w) => ({
      id: w.member.id,
      label: w.member.name,
      sublabel: w.member.title,
      value: w.count,
      valueLabel: `${w.count} / ${w.member.capacity} 件`,
      fraction: Math.min(w.count / w.member.capacity, 1),
      tone:
        w.count > w.member.capacity
          ? ("destructive" as const)
          : w.count >= w.member.capacity - 1
            ? ("warning" as const)
            : ("primary" as const),
      trailing:
        w.overdue > 0 ? (
          <Badge variant="destructive" size="sm" icon={<IconAlertTriangle />}>
            超過 {w.overdue}
          </Badge>
        ) : undefined,
      onSelect: () => setAssignee(w.member.id),
    }))

  // ── 更新系 ───────────────────────────────────
  const patch = (matterId: string, fn: (m: Matter) => Matter) =>
    setList((prev) => prev.map((m) => (m.id === matterId ? fn(m) : m)))

  const handleAssign = (matterId: string, memberId: string | null) =>
    patch(matterId, (m) => ({
      ...m,
      assigneeId: memberId,
      status: m.status === "受付待ち" && memberId ? "調査中" : m.status,
      events: [
        ...m.events,
        {
          id: `e-${Date.now()}`,
          at: nowStamp(),
          actor: viewerName,
          kind: "割当" as const,
          title: memberId ? `${memberName(memberId)} に割当` : "担当を外した",
        },
      ],
    }))

  const handleAdvance = (matterId: string) =>
    patch(matterId, (m) => {
      const next = NEXT_STATUS[m.status]
      if (!next) return m
      return {
        ...m,
        status: next,
        answeredAt: next === "回答済み" ? TODAY : m.answeredAt,
        events: [
          ...m.events,
          {
            id: `e-${Date.now()}`,
            at: nowStamp(),
            actor: viewerName,
            kind: next === "完了" ? ("完了" as const) : ("状態変更" as const),
            title: `${next}に変更`,
          },
        ],
      }
    })

  const handleHold = (matterId: string) =>
    patch(matterId, (m) => ({
      ...m,
      status: "保留",
      events: [
        ...m.events,
        {
          id: `e-${Date.now()}`,
          at: nowStamp(),
          actor: viewerName,
          kind: "保留" as const,
          title: "保留に変更",
        },
      ],
    }))

  const handleReply = (matterId: string, commentId: string, body: string) =>
    patch(matterId, (m) => ({
      ...m,
      thread: m.thread.map((c) =>
        c.id === commentId
          ? {
              ...c,
              replies: [
                ...c.replies,
                {
                  id: `r-${Date.now()}`,
                  side: "法務" as const,
                  author: viewerName,
                  affiliation: "法務第一グループ",
                  at: nowStamp(),
                  body,
                },
              ],
            }
          : c,
      ),
    }))

  const handleToggleResolved = (matterId: string, commentId: string) =>
    patch(matterId, (m) => ({
      ...m,
      thread: m.thread.map((c) =>
        c.id === commentId ? { ...c, resolved: !c.resolved } : c,
      ),
    }))

  const handleAddComment = (matterId: string, body: string) =>
    patch(matterId, (m) => ({
      ...m,
      thread: [
        ...m.thread,
        {
          id: `c-${Date.now()}`,
          side: "法務" as const,
          author: viewerName,
          affiliation: "法務第一グループ",
          at: nowStamp(),
          body,
          resolved: false,
          replies: [],
        },
      ],
    }))

  // ── 一覧（表）の列定義 ────────────────────────
  const columns = React.useMemo<ColumnDef<Matter, unknown>[]>(
    () => [
      {
        accessorKey: "title",
        header: "件名 / 案件番号",
        cell: ({ row }) => (
          <div className="min-w-0 max-w-[22rem]">
            <div className="truncate font-medium text-foreground">
              {row.original.title}
            </div>
            <div className="text-xs tabular-nums text-muted-foreground">
              {row.original.id}
            </div>
          </div>
        ),
      },
      {
        accessorKey: "department",
        header: "依頼元",
        cell: ({ row }) => (
          <div className="min-w-0 max-w-[16rem]">
            <div className="truncate text-sm">{row.original.department}</div>
            <div className="truncate text-xs text-muted-foreground">
              {row.original.requester}
            </div>
          </div>
        ),
      },
      {
        accessorKey: "category",
        header: "種類",
        cell: ({ row }) => (
          <Badge variant="outline" size="sm">
            {row.original.category}
          </Badge>
        ),
      },
      {
        accessorKey: "priority",
        header: "重要度",
        cell: ({ row }) => (
          <Badge variant={PRIORITY_VARIANT[row.original.priority]} size="sm">
            {row.original.priority}
          </Badge>
        ),
      },
      {
        id: "due",
        accessorFn: (m) => daysUntil(m.dueDate),
        header: "希望回答日",
        cell: ({ row }) => (
          <DueIndicator
            dueDate={row.original.dueDate}
            status={row.original.status}
          />
        ),
      },
      {
        accessorKey: "assigneeId",
        header: "法務担当",
        cell: ({ row }) =>
          row.original.assigneeId ? (
            <span className="text-sm">{memberName(row.original.assigneeId)}</span>
          ) : (
            <Badge variant="warning" size="sm">
              未割当
            </Badge>
          ),
      },
      {
        accessorKey: "status",
        header: "状態",
        cell: ({ row }) => (
          <Badge variant={STATUS_VARIANT[row.original.status]} size="sm">
            {row.original.status}
          </Badge>
        ),
      },
      {
        id: "openThread",
        accessorFn: (m) => openThreadCount(m),
        header: "未解決",
        cell: ({ row }) => {
          const n = openThreadCount(row.original)
          return n === 0 ? (
            <span className="text-sm text-muted-foreground">—</span>
          ) : (
            <Badge variant="info" size="sm" icon={<IconMessage2 />}>
              {n}
            </Badge>
          )
        },
      },
    ],
    [],
  )

  const filtersActive =
    query.trim() !== "" || category !== "all" || assignee !== "all" || onlyAlert

  const resetFilters = () => {
    setQuery("")
    setCategory("all")
    setAssignee("all")
    setOnlyAlert(false)
  }

  return (
    <div className="space-y-6">
      <DesktopPageHeader
        eyebrow={
          <span className="flex flex-wrap items-center gap-x-2 gap-y-1">
            <span>{companyName}</span>
            <span aria-hidden>·</span>
            <span>{departmentName}</span>
          </span>
        }
        title="法務相談・案件管理"
        subtitle={`表示中：${viewerName}　基準日 ${formatJpDate(TODAY)}`}
        actions={
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={reload}
            loading={loading}
          >
            <Icon icon={IconRefresh} size="sm" decorative />
            再読み込み
          </Button>
        }
      />

      {overdueCount > 0 ? (
        <Alert
          variant="destructive"
          icon={<IconAlertTriangle />}
          title={`希望回答日を過ぎている案件が ${overdueCount} 件あります`}
          description={`3日以内に期限を迎える案件が ${dueSoonCount} 件、依頼元の返信待ちになっている論点が ${openComments} 件あります。`}
        />
      ) : null}

      {/* ── 受付の統計 ─────────────────────────── */}
      <section aria-labelledby="stats-heading" className="space-y-4">
        <h2 id="stats-heading" className="sr-only">
          受付の統計
        </h2>
        {loading ? (
          <div className="grid gap-4 sm:grid-cols-2 md:grid-cols-4">
            {[0, 1, 2, 3].map((i) => (
              <Skeleton key={i} className="h-24 w-full rounded-lg" />
            ))}
          </div>
        ) : (
          <StatGroup items={stats} cols={{ base: 1, sm: 2, md: 4 }} />
        )}

        <div className="grid gap-4 lg:grid-cols-2">
          <Card>
            <CardHeader>
              <CardTitle as="h3">相談の種類ごとの内訳</CardTitle>
              <CardDescription>
                受付済みの全 {list.length} 件（完了分を含む）
              </CardDescription>
            </CardHeader>
            <CardContent>
              {loading ? (
                <Skeleton className="h-16 w-full rounded-md" />
              ) : (
                <DistributionBar
                  segments={categorySegments}
                  showLegend
                  totalLabel="合計"
                  valueFormat="integer"
                />
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle as="h3">法務メンバーの保有件数</CardTitle>
              <CardDescription>
                完了を除く保有件数と受け入れ上限。行を選ぶとその担当で絞り込みます。
              </CardDescription>
            </CardHeader>
            <CardContent>
              {loading ? (
                <div className="space-y-3">
                  {[0, 1, 2, 3, 4].map((i) => (
                    <Skeleton key={i} className="h-10 w-full rounded-md" />
                  ))}
                </div>
              ) : (
                <Leaderboard
                  label="法務メンバーの保有件数"
                  items={workload}
                  showRank={false}
                  max={Math.max(...members.map((m) => m.capacity))}
                />
              )}
            </CardContent>
          </Card>
        </div>
      </section>

      {/* ── 案件 ───────────────────────────────── */}
      <section aria-labelledby="matters-heading" className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
          <h2
            id="matters-heading"
            className="flex items-center gap-2 text-lg font-semibold text-foreground"
          >
            <Icon icon={IconScale} size="sm" decorative />
            相談案件（{filtered.length} / {list.length} 件）
          </h2>
          <SegmentedControl
            aria-label="案件の表示方法"
            fullWidth={false}
            options={[
              { value: "board", label: "段階別", icon: <IconLayoutColumns /> },
              { value: "list", label: "一覧", icon: <IconList /> },
            ]}
            value={view}
            onValueChange={(v) => setView(v as "board" | "list")}
          />
        </div>

        {/* 絞り込み */}
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          {/* SearchInput は Input / Select / Textarea と違い `label` prop を持たないため、
              並びを揃えるために Label を自前で添えている */}
          <div className="space-y-1.5">
            <Label htmlFor="matter-search">キーワード</Label>
            <SearchInput
              id="matter-search"
              placeholder="件名・番号・依頼元で検索"
              value={query}
              onValueChange={setQuery}
            />
          </div>
          <Select
            label="相談の種類"
            value={category}
            onChange={(e) =>
              setCategory(e.target.value as "all" | MatterCategory)
            }
          >
            <option value="all">すべての種類</option>
            {CATEGORIES.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </Select>
          <Select
            label="法務担当"
            value={assignee}
            onChange={(e) => setAssignee(e.target.value)}
          >
            <option value="all">すべての担当</option>
            <option value="unassigned">未割当のみ</option>
            {members.map((m) => (
              <option key={m.id} value={m.id}>
                {m.name}
              </option>
            ))}
          </Select>
          <div className="flex items-end gap-2">
            <Toggle
              variant="outline"
              size="default"
              pressed={onlyAlert}
              onPressedChange={setOnlyAlert}
              className="gap-1.5"
            >
              <Icon icon={IconAlertTriangle} size="sm" decorative />
              期限が近い・超過のみ
            </Toggle>
            {filtersActive ? (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={resetFilters}
              >
                絞り込み解除
              </Button>
            ) : null}
          </div>
        </div>

        {loading ? (
          <div className="space-y-3" aria-busy="true" aria-live="polite">
            <span className="sr-only">案件を読み込んでいます</span>
            {[0, 1, 2, 3, 4].map((i) => (
              <Skeleton key={i} className="h-20 w-full rounded-lg" />
            ))}
          </div>
        ) : filtered.length === 0 ? (
          <EmptyState
            headingLevel={3}
            icon={<Icon icon={IconInbox} size="xl" decorative />}
            title="該当する相談案件がありません"
            description="絞り込み条件を緩めるか、検索語を変えてみてください。"
            action={
              filtersActive ? (
                <Button type="button" variant="outline" onClick={resetFilters}>
                  絞り込みを解除する
                </Button>
              ) : undefined
            }
          />
        ) : view === "board" ? (
          <KanbanBoard
            columns={kanbanColumns}
            items={filtered}
            getItemId={(m) => m.id}
            getColumnId={(m) => m.status}
            columnWidth={288}
            emptyLabel="この段階の案件はありません"
            onCardSelect={(m) => setSelectedId(m.id)}
            renderCard={(m) => (
              <div className="space-y-2 text-left">
                <div className="flex flex-wrap items-center gap-1.5">
                  <Badge variant={PRIORITY_VARIANT[m.priority]} size="sm">
                    {m.priority}
                  </Badge>
                  <Badge variant="outline" size="sm">
                    {m.category}
                  </Badge>
                </div>
                <p className="text-sm font-medium leading-snug text-foreground">
                  {m.title}
                </p>
                <p className="text-xs text-muted-foreground">
                  {m.department}／{m.requester}
                </p>
                <DueIndicator dueDate={m.dueDate} status={m.status} />
                <div className="flex flex-wrap items-center gap-1.5 text-xs text-muted-foreground">
                  <span>担当：{memberName(m.assigneeId)}</span>
                  {openThreadCount(m) > 0 ? (
                    <Badge variant="info" size="sm" icon={<IconMessage2 />}>
                      未解決 {openThreadCount(m)}
                    </Badge>
                  ) : null}
                </div>
              </div>
            )}
          />
        ) : (
          <DataTable<Matter, unknown>
            columns={columns}
            data={filtered}
            filter={null}
            pageSize={10}
            caption="相談案件の一覧"
            captionClassName="sr-only"
            onRowClick={(m) => setSelectedId(m.id)}
            renderCard={(m) => (
              <ListCard
                title={m.title}
                description={`${m.department}／${m.requester}`}
                severity={
                  isOverdue(m) ? "critical" : isDueSoon(m) ? "warning" : undefined
                }
                tags={
                  <>
                    <Badge variant={PRIORITY_VARIANT[m.priority]} size="sm">
                      {m.priority}
                    </Badge>
                    <Badge variant="outline" size="sm">
                      {m.category}
                    </Badge>
                    <Badge variant={STATUS_VARIANT[m.status]} size="sm">
                      {m.status}
                    </Badge>
                  </>
                }
                status={
                  <DueIndicator
                    dueDate={m.dueDate}
                    status={m.status}
                    showDate={false}
                  />
                }
                meta={`${m.id}／担当 ${memberName(m.assigneeId)}`}
                trailing={null}
              />
            )}
          />
        )}
      </section>

      {/* ── 1件の詳細 ──────────────────────────── */}
      <Sheet
        open={selected !== null}
        onOpenChange={(open) => {
          if (!open) setSelectedId(null)
        }}
      >
        <SheetContent
          side="right"
          size="full"
          className="w-full sm:max-w-2xl lg:max-w-3xl"
          closeLabel="詳細を閉じる"
        >
          {selected ? (
            <>
              <SheetHeader>
                <SheetTitle className="pr-8 text-left">
                  {selected.title}
                </SheetTitle>
                <SheetDescription className="text-left">
                  {selected.id}／{selected.department}／依頼者 {selected.requester}
                </SheetDescription>
              </SheetHeader>
              <SheetBody>
                <MatterDetail
                  matter={selected}
                  onAssign={handleAssign}
                  onAdvance={handleAdvance}
                  onHold={handleHold}
                  onReply={handleReply}
                  onToggleResolved={handleToggleResolved}
                  onAddComment={handleAddComment}
                />
              </SheetBody>
            </>
          ) : null}
        </SheetContent>
      </Sheet>
    </div>
  )
}
